import React, { useState, useEffect } from 'react';
import { Github, Linkedin, Mail, Phone, ExternalLink, ChevronDown, Code, Database, Brain, BarChart3, MessageSquare, Activity, Download, MapPin, Calendar, Award, BookOpen } from 'lucide-react';

const Portfolio = () => {
  const [activeSection, setActiveSection] = useState('hero');
  const [isVisible, setIsVisible] = useState({});

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setActiveSection(entry.target.id);
            setIsVisible(prev => ({ ...prev, [entry.target.id]: true }));
          }
        });
      },
      { threshold: 0.6 }
    );

    document.querySelectorAll('section[id]').forEach((section) => {
      observer.observe(section);
    });

    return () => observer.disconnect();
  }, []);

  const scrollToSection = (id) => {
    document.getElementById(id)?.scrollIntoView({ behavior: 'smooth' });
  };

  const projects = [
    {
      title: "Resume Screening Bot",
      description: "Built a resume ranking tool using TF-IDF and cosine similarity to match job descriptions to candidate resumes. Designed the front-end in Streamlit for quick visual interaction and usability.",
      icon: <Code className="w-6 h-6" />,
      tech: ["Python", "TF-IDF", "Streamlit", "NLP", "Cosine Similarity"],
      gradient: "from-blue-500 to-purple-600"
    },
    {
      title: "Customer Service REST API",
      description: "Developed a robust Spring Boot REST API for customer service operations with JWT authentication, ticket management, and user roles. Implemented MySQL database integration with comprehensive error handling and logging.",
      icon: <MessageSquare className="w-6 h-6" />,
      tech: ["Java", "Spring Boot", "MySQL", "JWT", "REST API", "JPA"],
      gradient: "from-green-500 to-blue-500"
    },
    {
      title: "Automated Ticket Classification System",
      description: "Built an ML-powered ticket classification system using NLP to automatically categorize and prioritize customer support tickets. Achieved 94% accuracy with automated routing to appropriate support teams.",
      icon: <Brain className="w-6 h-6" />,
      tech: ["Python", "scikit-learn", "NLP", "TF-IDF", "Flask", "PostgreSQL"],
      gradient: "from-purple-500 to-pink-500"
    },
    {
      title: "Scalable Analytics Data Pipeline",
      description: "Designed and implemented ETL pipeline for processing customer interaction data at scale. Built data warehousing solution with automated reporting and real-time analytics dashboard for support metrics.",
      icon: <BarChart3 className="w-6 h-6" />,
      tech: ["Python", "Apache Kafka", "PostgreSQL", "ETL", "Data Warehousing", "Analytics"],
      gradient: "from-red-500 to-orange-500"
    }
  ];

  const skills = {
    "Languages": ["Python", "JavaScript", "TypeScript", "Java", "SQL", "HTML", "CSS", "Golang", "C"],
    "Frameworks": ["React", "Flask", "Vue", "pandas", "NumPy", "scikit-learn", "TensorFlow"],
    "Tools": ["Git", "VS Code", "Postman", "Jupyter", "Streamlit", "Figma", "Tableau"],
    "Databases": ["PostgreSQL", "MySQL", "MongoDB", "Redis"],
    "Concepts": ["REST APIs", "UI/UX", "A/B Testing", "OOP", "Data Security", "Scalable Systems", "Agile"]
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-purple-900 to-slate-900 text-white">
      {/* Your content goes here */}
    </div>
  );
};

export default Portfolio;
